let state,uiStock,uiDraftStock,numberFrame=null,view='calc',detailPage={},settingsReturn={view:'calc',scroll:0},placesTab='markets',eventFilter='all',search='',categoryFilter='',busy=false,storageReadOnly=false,saveTimer,toastTimer,photoCache=new Map(),demoPhotos=new Map(),reportMonth=today().slice(0,7);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
