const icon=(name,size=20)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round"><path d="${iconPaths[name]||iconPaths.box}"/></svg>`;
const star=(size=100)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 100 100" fill="currentColor"><path d="m60 1 3 32 35 9-31 17-1 38-25-28L4 77l19-31L13 15l31 13Z"/></svg>`;
function merchArt(category){if(category==='Брелок')return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120" fill="none"><ellipse cx="60" cy="22" rx="14" ry="16" stroke="currentColor" stroke-width="4"/><path d="M60 36v12" stroke="currentColor" stroke-width="5"/><path d="m67 40 6 21 23 7-21 14-1 26-19-19-26 2 15-23-5-23 23 9Z" fill="currentColor"/><path d="m64 58 2 9 10 4-9 5-1 10-7-7-11 1 6-9-1-9 9 3Z" fill="white" opacity=".8"/></svg>`;
if(category==='Стенд')return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120"><ellipse cx="60" cy="102" rx="35" ry="8" fill="currentColor" opacity=".35"/><path d="M58 102V86" stroke="currentColor" stroke-width="6"/><path d="M40 22 43 9 56 20 70 17 81 8 84 27Q100 46 88 62L93 86H27l6-25Q23 41 40 22Z" fill="currentColor"/><path d="M46 45h1m23-1h1" stroke="white" stroke-width="7" stroke-linecap="round"/><path d="m54 57 5 4 5-4" fill="none" stroke="white" stroke-width="3" stroke-linecap="round"/><path d="m42 75 8-7 9 7 10-7 10 7" fill="none" stroke="white" stroke-width="3" opacity=".6"/></svg>`;
if(['Стикер','Стикерпак'].includes(category))return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120"><rect x="22" y="15" width="77" height="87" rx="9" fill="white"/><rect x="29" y="22" width="63" height="73" rx="5" fill="currentColor" opacity=".16"/><path d="m45 34 5 12 14-4-5 13 8 10-14 1-6 13-6-12-14-2 10-10-2-14 11 6Z" fill="currentColor"/><circle cx="77" cy="73" r="15" fill="currentColor"/><path d="m70 72 5 5 8-9" fill="none" stroke="white" stroke-width="3" stroke-linecap="round"/><path d="M76 103h14a9 9 0 0 0 9-9V80Z" fill="white"/><path d="M76 103V87a7 7 0 0 1 7-7h16" fill="none" stroke="currentColor" opacity=".25"/></svg>`;
if(category==='Значок')return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120"><circle cx="60" cy="60" r="40" fill="currentColor"/><circle cx="60" cy="60" r="34" fill="none" stroke="white" opacity=".5"/><path d="m65 33 3 18 19 4-17 10-1 20-14-15-19 4 10-17-5-18 17 7Z" fill="white"/></svg>`;
return `<svg aria-hidden="true" width="45" height="45" viewBox="0 0 120 120"><rect x="23" y="12" width="74" height="96" rx="4" fill="white"/><rect x="29" y="18" width="62" height="75" rx="2" fill="currentColor" opacity=".2"/><circle cx="64" cy="43" r="13" fill="currentColor"/><path d="m30 92 22-29 14 16 12-11 13 24Z" fill="currentColor"/><path d="M36 100h47" stroke="currentColor" stroke-width="2" opacity=".5"/></svg>`;}
function thumb(item){return `<span class="thumb ${esc(item.color||'red')}">${item.photo?`<img data-photo="${esc(item.photo)}" alt="${esc(item.name)}" loading="lazy" decoding="async">`:merchArt(item.category)}</span>`;}
const readPhoto=id=>isDemo?Promise.resolve(demoPhotos.get(id)||null):getPhoto(id);
const storePhoto=(id,blob)=>isDemo?Promise.resolve(demoPhotos.set(id,blob)):setPhoto(id,blob);
function releasePhotoCache(){
  const active=new Set([...document.querySelectorAll('#app img[data-photo],#sheet[open] img[data-photo]')].map(img=>img.dataset.photo));
  for(const [key,pending] of photoCache) if(!active.has(key)){
    photoCache.delete(key);
    pending.then(url=>{if(url)URL.revokeObjectURL(url);});
  }
}
async function hydratePhotos(){
  const images=[...document.querySelectorAll('#app img[data-photo],#sheet[open] img[data-photo]')];
  releasePhotoCache();
  await Promise.all(images.map(async img=>{
    const key=img.dataset.photo;
    if(!photoCache.has(key))photoCache.set(key,readPhoto(key).then(blob=>blob?URL.createObjectURL(blob):null).catch(()=>null));
    const url=await photoCache.get(key);
    if(!img.isConnected)return;
    if(url)img.src=url;
    else{img.removeAttribute('data-photo');img.replaceWith(document.createTextNode('Фото недоступно'));}
  }));
  releasePhotoCache();
}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function haptic(){try{const tg=globalThis.Telegram?.WebApp;if(tg?.initData&&tg?.isVersionAtLeast?.('6.1'))tg.HapticFeedback?.impactOccurred('light');}catch{}}
function applyTheme(){const theme=state.settings.theme||'auto';const dark=theme==='dark'||(theme==='auto'&&(globalThis.Telegram?.WebApp?.colorScheme==='dark'||(!globalThis.Telegram?.WebApp?.initData&&matchMedia('(prefers-color-scheme: dark)').matches)));document.documentElement.dataset.theme=dark?'dark':'light';document.querySelector('meta[name=theme-color]').content=dark?'#151619':'#f7f8fa';try{const tg=globalThis.Telegram?.WebApp;if(tg?.initData&&tg?.isVersionAtLeast?.('6.1')){tg.setHeaderColor(dark?'#151619':'#f7f8fa');tg.setBackgroundColor(dark?'#151619':'#f7f8fa');}if(tg?.initData&&tg?.isVersionAtLeast?.('7.10'))tg.setBottomBarColor(dark?'#151619':'#f7f8fa');}catch{}}
function persistDraft(){if(storageReadOnly)return;clearTimeout(saveTimer);state.updatedAt=Date.now();if(!isDemo)saveTimer=setTimeout(()=>saveState(state).catch(e=>toast(e.message)),220);}
async function commit(fn,message){if(storageReadOnly)throw new Error('Ошибка загрузки. Для сохранения восстанови копию в настройках.');if(busy)return false;busy=true;clearTimeout(saveTimer);try{const next=clone(state);const result=await fn(next);next.updatedAt=Date.now();validateState(next);if(!isDemo)await saveState(next);state=next;render();if(message)toast(message);return result??true;}finally{busy=false;}}
function navigate(next,position=0){if(next==='settings'&&view!=='settings')settingsReturn={view,scroll:window.scrollY};window.scrollTo({top:0,left:0,behavior:'instant'});view=next;render();if(position>0){window.scrollTo({top:position,left:0,behavior:'instant'});}haptic();}
function heading(title,action=''){return `<div class="page-heading"><h1>${esc(title)}</h1>${action}</div>`;}
function stat(label,value,cls=''){return `<div><div class="stat-label">${label}</div><div class="stat-value ${cls}">${value}</div></div>`;}
function empty(iconName,title,description,buttons=''){return `<div class="card empty-state"><span class="empty-icon">${icon(iconName,32)}</span><h2>${title}</h2><p>${description}</p><div class="empty-actions">${buttons}</div></div>`;}
function render(){if(numberFrame!==null){cancelAnimationFrame(numberFrame);numberFrame=null;}uiStock=stockLevels(state);uiDraftStock=state.editingId?stockLevels(state,state.editingId):uiStock;applyTheme();app.innerHTML=`<div class="app-shell"><header class="topbar"><button class="brand" data-action="nav" data-view="calc" aria-label="Солянка — к калькулятору"><img src="./assets/logo.png" alt="Солянка"></button><div class="topbar-right"><span class="local-status"><span class="status-dot"></span>${isDemo?'Демо без сохранения':'Данные на устройстве'}</span><button class="icon-btn" data-action="theme-toggle" aria-label="Переключить светлую и тёмную тему">${icon(document.documentElement.dataset.theme==='dark'?'sun':'moon',18)}</button><button class="icon-btn" data-action="toggle-settings" aria-label="${view==='settings'?'Закрыть настройки':'Настройки и резервные копии'}" aria-expanded="${view==='settings'}" aria-controls="main">${icon(view==='settings'?'close':'settings',20)}</button></div></header>${isDemo?`<div class="demo-banner"><span>${icon('info',14)} Демо · без сохранения</span><button data-action="exit-demo">Мои данные</button></div>`:''}<main id="main">${view==='calc'?calculator():view==='inventory'?inventory():view==='places'?places():settings()}</main></div><nav class="bottom-nav" aria-label="Основная навигация">${[['inventory','box','Мерч'],['calc','calc','Расчёт'],['places','calendar','Площадки']].map(([v,i,l])=>`<button data-action="nav" data-view="${v}" class="${view===v?'active':''}" ${view===v?'aria-current="page"':''}>${icon(i)}<span>${l}</span></button>`).join('')}</nav>`;prepareInputs(app);hydratePhotos();}
const goalNames={market:'Расходы на участие',all:'Все вложения',plus:'Вложения и прибыль'};
function summary(p){return `<div class="card summary-card"><div class="summary-main"><span>Выручка<strong class="money">${money(p.revenue)}</strong></span><span>Прибыль с проданного<strong class="money ${p.profit>=0?'positive':'negative'}">${money(p.profit)}</strong></span><button class="info-button" data-action="metrics-info" aria-label="Как считаются результаты">${icon('info',20)}</button></div><div class="summary-bottom"><span>Все вложения <b>${money(p.costs+p.procurement)}</b></span><span>После вложений <b class="${p.cash>=0?'positive':'negative'}">${money(p.cash)}</b></span></div></div>`;}
function calculator(){
  const plan=state.draft,p=projection(plan),step=plan.lines.length?Math.max(0,Math.min(Number.isInteger(plan.uiStep)?plan.uiStep:0,3)):0;
  const pages=[`<section class="section"><div class="section-top"><h2>Мерч с собой <span class="section-count">${plan.lines.length} поз.</span></h2></div><div class="plan-lines">${p.lines.map(line=>planLine(line,plan.mode)).join('')||`<div class="card empty-inline">Выбери мерч из инвентаря<br>или создай товар.</div>`}</div><button class="dashed-add" data-action="pick-item">${icon('plus',16)} Выбрать мерч</button></section>`,`<section class="section"><div class="section-top"><h2>Акции <span class="section-count">Наборы</span></h2><button class="text-btn" data-action="promo" ${!plan.lines.length?'disabled':''}>${icon('plus',14)} Набор</button></div>${p.bundles.map(bundle=>promoCard(bundle)).join('')||`<div class="card empty-inline">Создай набор с общей ценой.</div>`}</section>`,`<section class="section"><div class="section-top"><h2>Расходы</h2></div><div class="card expense-card"><div class="expense-row">${icon('shelf',17)}<span>Место / стол</span><input aria-label="Стоимость места на маркете" type="number" min="0" max="1000000000" step="0.01" value="${plan.table}" data-change="table"><span style="flex:0;color:var(--muted)">₽</span></div>${plan.expenses.map(e=>`<div class="expense-row">${icon(e.name==='Дорога'?'pin':'bag',17)}<span>${esc(e.name)}</span><input aria-label="${esc(e.name)} — сумма" type="number" min="0" max="1000000000" step="0.01" value="${e.amount}" data-change="expense" data-id="${esc(e.id)}"><button class="remove" data-action="remove-expense" data-id="${esc(e.id)}" aria-label="Удалить расход ${esc(e.name)}">${icon('close',14)}</button></div>`).join('')}</div><button class="text-btn" data-action="add-expense">${icon('plus',14)} Добавить расход</button><div class="expense-total"><span>Расходы на участие</span><strong data-expense-total>${money(p.costs)}</strong></div></section>${plan.mode==='simple'?`<div class="goal-extra" style="margin-bottom:20px"><label for="round-step">Округлять вверх до</label><select id="round-step" data-change="round" style="width:100px;min-height:36px;padding:8px;font-size:12px">${[1,10,50,100].map(n=>`<option value="${n}" ${plan.round===n?'selected':''}>${n} ₽</option>`).join('')}</select></div>`:''} ${plan.mode==='simple'?`<section class="section"><div class="section-top"><h2>Цель расчёта</h2></div><div class="goal-options">${[['market','bag','Расходы <br>на участие'],['all','target','Все <br>вложения'],['plus','trend','Вложения <br>+ прибыль']].map(([id,i,label])=>`<div class="goal-option ${plan.goal===id?'active':''}" role="group"><button class="info-button" data-action="goal-info" data-value="${id}" aria-label="О цели: ${goalNames[id]}">${icon('info',14)}</button><button data-action="goal" data-value="${id}" class="goal-select" aria-pressed="${plan.goal===id}" style="text-align:left;width:100%;padding:0"><span class="goal-icon">${icon(i,20)}</span><span class="goal-label" style="display:block;margin-top:10px">${label}</span></button></div>`).join('')}</div>${plan.goal==='plus'?`<div class="goal-extra"><span>Прибыль от вложений</span><label class="inline-number"><input aria-label="Желаемая прибыль в процентах" type="number" min="0" max="10000" step="1" value="${plan.profit}" data-change="profit"><span>%</span></label></div>`:''}</section>`:''}`,`<section class="section"><h2>Цены на маркет</h2><div class="plan-lines">${p.lines.map(l=>`<div class="card result-line"><span>${esc(l.name)}<small>${l.qty} шт. с собой · <span data-sold-for="${esc(l.itemId)}">${l.sold}</span> продам</small></span><strong><span data-price-for="${esc(l.itemId)}">${money(l.price)}</span> / шт.</strong></div>`).join('')}</div><p class="sheet-description" id="calc-note">${calcNote(p)}</p></section>`];
  return `${heading('Калькулятор маркета')}<div class="wizard-nav" aria-label="Этапы расчёта">${['Мерч','Акции','Расходы','Итог'].map((name,i)=>`<button data-action="calc-step" data-value="${i}" class="${i===step?'active':''}" aria-current="${i===step?'step':'false'}" ${i>0&&!plan.lines.length?'disabled':''}><span>${i+1}</span>${name}</button>`).join('')}</div><div class="calc-layout"><aside class="summary-column"><div id="summary">${summary(p)}</div></aside><div class="calc-content">${state.editingId?`<p class="saved-edit">План: ${esc(state.events.find(e=>e.id===state.editingId)?.name)}</p>`:''}<div class="mode-row"><div class="segmented" aria-label="Режим калькулятора"><button class="${plan.mode==='simple'?'active':''}" data-action="mode" data-value="simple">Простой</button><button class="${plan.mode==='pro'?'active':''}" data-action="mode" data-value="pro">Про</button></div><button class="text-btn" data-action="reset-draft" aria-label="Очистить текущий расчёт">Сбросить</button></div>${step===1||step===3?`<section class="section"><div class="card range-card"><div class="range-heading"><label for="sell-percent">Планирую продать</label><output class="range-output" id="percent-output">${plan.sellPercent}%</output></div><div class="range-wrap"><input id="sell-percent" aria-label="Процент ожидаемых продаж" type="range" min="0" max="100" step="1" value="${plan.sellPercent}" data-live="percent" style="--range-pct:${plan.sellPercent}%"></div><div class="range-meta"><span>0%</span><span id="sold-output">${p.sold} из ${p.total} шт.</span><span>100%</span></div></div></section>`:''}${pages[step]}<div class="wizard-actions">${step?`<button class="button secondary" data-action="calc-step" data-value="${step-1}">${icon('back',16)} Назад</button>`:''}${step<3?`<button class="button" data-action="calc-step" data-value="${step+1}" ${!plan.lines.length?'disabled':''}>Далее ${icon('arrow',16)}</button>`:`<button class="button" data-action="save-event">${state.editingId?'Обновить маркет':'Сохранить маркет'}</button>`}</div></div></div>`;
}
function calcNote(p){if(!p.total)return 'Добавь мерч для расчёта.';if(!p.sold)return 'При 0% продаж выручки нет. Увеличь прогноз.';let note=state.draft.mode==='simple'?'Цены зависят от прогноза и не ниже себестоимости.':'Прогноз по твоим ценам.';if(p.floored)note+=' Из-за порога себестоимости выручка может превышать цель.';if(p.bundles.some(b=>b.clamped))note+=' Наборы ограничены прогнозом и запасом.';if(state.draft.mode==='simple'&&p.shortfall>0)note+=` До цели не хватает ${money(p.shortfall)}. Измени прогноз или наборы.`;return note;}
function planLine(line,mode){return `<article class="card plan-line">${thumb({...line,photo:line.photo||state.inventory.find(i=>i.id===line.itemId)?.photo,color:state.inventory.find(i=>i.id===line.itemId)?.color})}<div><div class="line-name">${esc(line.name)}</div><div class="line-meta">Себестоимость <span data-cost-for="${esc(line.itemId)}">${money(line.cost)}</span> / шт. · <span data-sold-for="${esc(line.itemId)}">${line.sold}</span> прод.</div></div><div class="line-price"><span data-price-for="${esc(line.itemId)}">${money(line.price)}</span><small>${mode==='simple'?'расчётная цена':'цена продажи'}</small></div><div class="line-controls"><label>Беру<input aria-label="Количество на маркет: ${esc(line.name)}" type="number" min="1" max="${freeStock(line.itemId,state.editingId)}" step="1" value="${line.qty}" data-change="line-qty" data-id="${esc(line.itemId)}"></label><span class="small muted">из ${freeStock(line.itemId,state.editingId)} доступных</span><button class="remove" data-action="remove-line" data-id="${esc(line.itemId)}" aria-label="Убрать ${esc(line.name)} из расчёта">${icon('close',15)}</button></div>${mode==='pro'?`<div class="price-range"><div class="price-range-top"><label>Себестоимость / шт.</label><input aria-label="Себестоимость в расчёте: ${esc(line.name)}" type="number" min="0" max="1000000000" step="0.01" value="${line.cost}" data-change="line-cost" data-id="${esc(line.itemId)}"></div><div class="price-range-top"><span>Цена продажи</span><input aria-label="Точная цена: ${esc(line.name)}" type="number" min="0" max="1000000000" step="0.01" value="${line.price}" data-change="line-price" data-id="${esc(line.itemId)}"></div><input id="price-${esc(line.itemId)}" type="range" aria-label="Цена продажи: ${esc(line.name)}" min="0" max="${Math.max(1000,line.cost*6,Math.ceil(line.price/100)*100)}" step="10" value="${line.price}" data-live="price" data-id="${esc(line.itemId)}" style="--range-pct:${line.price/Math.max(1000,line.cost*6,Math.ceil(line.price/100)*100)*100}%"></div>`:''}</article>`;}
function promoCard(bundle){return `<article class="card promo-card"><div class="promo-head"><h3>${icon('bag',15)} ${esc(bundle.name)}</h3><button class="info-button" data-action="promo" data-id="${esc(bundle.id)}" aria-label="Редактировать набор ${esc(bundle.name)}">${icon('edit',15)}</button></div><div class="promo-parts">${bundle.parts.map(part=>`${part.qty} × ${esc(state.draft.lines.find(l=>l.itemId===part.itemId)?.name||'')}`).join(' + ')}</div><div class="promo-footer"><span><strong>${money(bundle.price)}</strong> за набор</span><label>Продам <input aria-label="План продаж набора ${esc(bundle.name)}" type="number" min="0" max="${bundle.max}" step="1" value="${bundle.count}" data-change="promo-count" data-id="${esc(bundle.id)}"> шт.</label></div><div class="range-wrap"><input type="range" aria-label="Количество наборов: ${esc(bundle.name)}" min="0" max="${bundle.max}" step="1" value="${bundle.count}" data-live="promo" data-id="${esc(bundle.id)}" style="--range-pct:${bundle.max?bundle.count/bundle.max*100:0}%"></div><div class="range-meta"><span>0 наборов</span><span>до ${bundle.max} по прогнозу</span></div>${bundle.clamped?'<div class="notice">Количество ограничено прогнозом.</div>':''}</article>`;}
function scheduleNumbers(){if(numberFrame===null)numberFrame=requestAnimationFrame(()=>{numberFrame=null;updateNumbers();});}
function updateNumbers(){
  if(view!=='calc')return;
  const p=projection(state.draft),lines=new Map(p.lines.map(line=>[line.itemId,line]));
  const el=document.querySelector('#summary');if(el)el.innerHTML=summary(p);
  const out=document.querySelector('#percent-output');if(out)out.textContent=state.draft.sellPercent+'%';
  const sold=document.querySelector('#sold-output');if(sold)sold.textContent=`${p.sold} из ${p.total} шт.`;
  for(const e of document.querySelectorAll('[data-price-for]')){const line=lines.get(e.dataset.priceFor);if(line)e.textContent=money(line.price);}
  for(const e of document.querySelectorAll('[data-sold-for]')){const line=lines.get(e.dataset.soldFor);if(line)e.textContent=line.sold;}
  for(const e of document.querySelectorAll('[data-cost-for]')){const line=lines.get(e.dataset.costFor);if(line)e.textContent=money(line.cost);}
  for(const e of document.querySelectorAll('[data-live=price]')){const line=lines.get(e.dataset.id);if(line&&e!==document.activeElement){e.max=Math.max(Number(e.max),Math.ceil(line.price/100)*100);e.value=line.price;e.style.setProperty('--range-pct',line.price/Number(e.max)*100+'%');}}
  for(const b of p.bundles){
    const number=document.querySelector(`[data-change="promo-count"][data-id="${b.id}"]`),range=document.querySelector(`[data-live="promo"][data-id="${b.id}"]`);
    if(number){number.max=b.max;if(number!==document.activeElement)number.value=b.count;}
    if(range){range.max=b.max;range.value=b.count;range.style.setProperty('--range-pct',(b.max?b.count/b.max*100:0)+'%');const label=range.closest('.promo-card').querySelector('.range-meta');if(label)label.innerHTML=`<span>0 наборов</span><span>до ${b.max} по прогнозу</span>`;}
  }
  for(const e of document.querySelectorAll('[data-expense-total]'))e.textContent=money(p.costs);
  for(const id of ['calc-note','mobile-note']){const n=document.getElementById(id);if(n)n.textContent=calcNote(p);}
}
function inventory(){const total=state.inventory.reduce((n,i)=>n+i.qty,0),free=state.inventory.reduce((n,i)=>n+freeStock(i.id),0),value=state.inventory.reduce((n,i)=>n+i.qty*i.cost,0);const items=state.inventory.filter(i=>!i.archived&&(!categoryFilter||i.category===categoryFilter)&&i.name.toLowerCase().includes(search.toLowerCase()));return `${heading('Твоя коллекция',state.inventory.some(i=>!i.archived)?`<button class="button" data-action="new-item">${icon('plus',17)} Добавить <span class="long-label">мерч</span></button>`:'')}${!state.inventory.some(i=>!i.archived)?empty('box','Нет товаров','Добавь мерч, количество и себестоимость за штуку.',`<button class="button" data-action="new-item">${icon('plus',16)} Добавить товар</button>${!isDemo?'<button class="button secondary" data-action="demo">Открыть демо</button>':''}`):`<div class="inventory-overview">${[['В наличии, шт.',total],['Свободно, шт.',free],['Стоимость остатка',money(value)]].map(([l,v])=>`<div class="overview-stat"><div class="stat-value">${v}</div><div class="stat-label">${l}</div></div>`).join('')}</div><div class="toolbar"><label class="searchbox">${icon('search',17)}<input id="inventory-search" placeholder="Поиск мерча" aria-label="Поиск товаров" value="${esc(search)}"></label><select id="category-filter" aria-label="Категория товаров"><option value="">Все виды</option>${categories.map(c=>`<option ${categoryFilter===c?'selected':''}>${c}</option>`).join('')}</select></div><div class="inventory-grid" id="inventory-grid">${items.map(item=>inventoryCard(item)).join('')||'<div class="muted small">Ничего не найдено.</div>'}</div>`}`;}
function inventoryCard(item){const free=freeStock(item.id),held=(uiStock.get(item.id)?.held||0);return `<article class="card item-card"><div class="item-art">${thumb(item)}</div><button class="icon-btn item-menu" data-action="item-menu" data-id="${esc(item.id)}" aria-label="Управление товаром ${esc(item.name)}">${icon('more',16)}</button><div class="item-body"><div class="item-category">${esc(item.category)}</div><h3 class="item-name">${esc(item.name)}</h3><div class="item-numbers">${stat('Себестоимость / шт.',money(item.cost))}${stat('Обычная цена',money(item.price))}</div><div class="stock-pill"><span>Свободно <strong>${free} шт.</strong></span><span class="muted">Всего ${item.qty}</span></div><div class="item-bottom"><span>${held?`Распределено ${held} шт.`:'Не распределено'}</span><button data-action="add-to-plan" data-id="${esc(item.id)}" ${free<1?'disabled':''}>${icon('plus',12)} В расчёт</button></div></div></article>`;}
function places(){const list=placesTab==='markets'?state.events.filter(e=>eventFilter==='all'||(eventFilter==='completed'?e.status==='completed':e.status!=='completed')):state.shelves;return `${heading('Площадки',(placesTab==='markets'?state.events.length:state.shelves.length)?`<button class="button" data-action="${placesTab==='markets'?'new-market':'new-shelf'}">${icon('plus',16)} ${placesTab==='markets'?'Маркет':'Полка'}</button>`:'')}<div class="segmented place-tabs"><button class="${placesTab==='markets'?'active':''}" data-action="places-tab" data-value="markets">Маркеты <span class="reduced">${state.events.length}</span></button><button class="${placesTab==='shelves'?'active':''}" data-action="places-tab" data-value="shelves">Полки <span class="reduced">${state.shelves.length}</span></button></div>${placesTab==='markets'&&state.events.length?`<div class="filter-row">${[['all','Все'],['active','Активные'],['completed','Проведены']].map(([v,l])=>`<button class="pill-filter ${eventFilter===v?'active':''}" data-action="event-filter" data-value="${v}">${l}</button>`).join('')}</div>`:''}${list.length?`<div class="place-list">${[...list].sort((a,b)=>(a.status==='completed')-(b.status==='completed')||(a.date||'9999').localeCompare(b.date||'9999')).map(p=>placesTab==='markets'?eventCard(p):shelfCard(p)).join('')}</div>`:empty(placesTab==='markets'?'calendar':'shelf',placesTab==='markets'?'Нет маркетов':'Нет полок',placesTab==='markets'?'Сохрани расчёт, затем внеси продажи.':'Укажи аренду и мерч для учёта продаж.',`<button class="button" data-action="${placesTab==='markets'?'new-market':'new-shelf'}">${icon('plus',16)} ${placesTab==='markets'?'Подготовить маркет':'Добавить полку'}</button>`)}`;}
function eventCard(event){const p=projection(event.plan),actual=event.sales.reduce((n,s)=>n+s.revenue,0),sold=Object.values(soldCounts(event)).reduce((a,b)=>a+b,0),date=event.date?new Date(event.date+'T12:00:00'):null;return `<article class="card place-card"><div class="place-head"><div class="date-tile"><strong>${date?date.getDate():'—'}</strong><small>${date?date.toLocaleDateString('ru-RU',{month:'short'}):'дата'}</small></div><div><h3>${esc(event.name)}</h3><p>${esc(event.address||'Без адреса')}</p><span class="badge ${event.status==='completed'?'done':event.status==='live'?'live':''}">${event.status==='completed'?icon('check',11):icon('clock',11)} ${event.status==='completed'?'Проведено':event.status==='live'?'Продажи':'В планах'}</span></div></div><div class="place-metrics">${stat(event.status==='planned'?'Прогноз выручки':'Выручка по факту',money(event.status==='planned'?p.revenue:actual))}${stat(event.status==='planned'?'Вложения':'Продано / взято',event.status==='planned'?money(p.procurement+p.costs):`${sold} / ${p.total} шт.`)}</div><div class="place-actions"><button class="button secondary compact" data-action="event-detail" data-id="${esc(event.id)}">Открыть ${icon('arrow',13)}</button>${event.status!=='completed'?`<button class="button compact" data-action="event-sale" data-id="${esc(event.id)}">${icon('plus',13)} Продажи</button>`:''}</div><div class="place-stock">${event.plan.lines.length} поз. · ${p.total} шт. ${event.status==='completed'?'было с собой':'выделено'} · ${event.plan.promos.length} акций</div></article>`;}
function shelfCard(shelf){const r=shelfReport(shelf),count=Object.values(shelf.stock).reduce((a,b)=>a+b,0),due=shelf.nextCheck&&shelf.nextCheck<=today();return `<article class="card place-card"><div class="place-head"><span class="shelf-icon">${icon('shelf',25)}</span><div><h3>${esc(shelf.name)}</h3><p>${esc(shelf.address||'Без адреса')}</p><span class="badge">${money(shelf.rent)} / месяц${shelf.commission?` · ${shelf.commission}% комиссии`:''}</span></div></div><div class="place-metrics">${stat('Выручка за месяц',money(r.revenue))}${stat('На полке',`${count} шт.`)}</div><div class="place-actions"><button class="button secondary compact" data-action="shelf-detail" data-id="${esc(shelf.id)}">Открыть ${icon('arrow',13)}</button><button class="button compact" data-action="shelf-sale" data-id="${esc(shelf.id)}" ${count?'':'disabled'}>Продажи</button></div>${due?`<div class="due">${icon('clock',14)} Пора проверить остатки</div>`:`<div class="place-stock">Проверка: ${shelf.nextCheck?fmtDate(shelf.nextCheck):'не задана'}</div>`}</article>`;}
function settings(){return `${heading('Настройки')}<div class="settings-grid"><section class="card settings-card"><h2>Тема</h2><p>Авто — по теме Telegram или системы.</p><div class="segmented">${[['auto','Авто'],['light','Светлая'],['dark','Тёмная']].map(([v,l])=>`<button class="${state.settings.theme===v?'active':''}" data-action="theme" data-value="${v}">${l}</button>`).join('')}</div></section><section class="card settings-card" id="backup-settings"><h2>Резервная копия</h2><p>Сохраняй копию после закупок и маркетов. Храни файл вне кэша Telegram: он поможет восстановить данные или перенести их на другой телефон.</p><div class="settings-actions"><button class="button secondary" data-action="export">${icon('download',16)} Сохранить копию</button><button class="button ghost" data-action="import">${icon('upload',16)} Восстановить</button></div><button class="text-btn" data-action="backup-notice-info">${icon('info',14)} О хранении данных</button></section><section class="card settings-card"><h2>О расчёте</h2><p>Прибыль учитывает себестоимость проданного и участие. Результат после всех вложений — закупку всего взятого мерча.</p><button class="text-btn" data-action="metrics-info">Подробнее ${icon('arrow',14)}</button></section><section class="card settings-card"><h2>Демо</h2><p>Расчёты, маркеты и полки на примере. Изменения не сохраняются.</p><button class="button secondary" data-action="demo">Открыть демо ${icon('arrow',15)}</button></section></div><p class="settings-note">Солянка · версия 1.1<br>Данные на устройстве, без синхронизации. Фото сжимаются до 800 px.<br>Обновлено: ${new Date(state.updatedAt).toLocaleString('ru-RU')}</p>`;}

function closeSheet(){sheet.close();sheet.innerHTML='';releasePhotoCache();}
function setSheet(title,body){sheet.innerHTML=`<div class="sheet-header"><h2 id="sheet-title">${title}</h2><button class="icon-btn" data-action="close-sheet" aria-label="Закрыть">${icon('close',17)}</button></div><div class="sheet-body">${body}</div>`;prepareInputs(sheet);if(!sheet.open)sheet.showModal();hydratePhotos();sheet.scrollTop=0;}
function info(title,copy,foot='Цены рассчитаны под твой прогноз продаж.'){setSheet(title,`<p class="info-copy">${copy}</p><div class="info-foot">${foot}</div><div class="sheet-footer"><button class="button" data-action="close-sheet">Понятно</button></div>`);}
function field(label,name,value='',type='text',attrs='',hint=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${attrs}>${hint?`<small>${hint}</small>`:''}</label>`;}
function selectField(label,name,options,value){return `<label class="field"><span>${label}</span><select name="${name}">${options.map(o=>{const [v,l]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(l)}</option>`;}).join('')}</select></label>`;}
const formNum=(form,name,fallback=0)=>{const value=form.elements.namedItem(name)?.value;return value===''||value===undefined?fallback:Number(value);};
function openForm(title,body,label,onSubmit){setSheet(title,`<form id="sheet-form">${body}<div class="form-error" role="alert"></div><div class="sheet-footer"><button type="submit" class="button">${label}</button></div></form>`);const form=sheet.querySelector('form');form.addEventListener('submit',async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;try{await onSubmit(form);}catch(err){const error=form.querySelector('.form-error');if(error.isConnected)error.textContent=err.message;else toast(err.message);}finally{if(button.isConnected)button.disabled=false;}});return form;}
function backupNotice(){setSheet('Резервные копии',`<div class="backup-notice-icon">${icon('download',25)}</div><p class="sheet-description">Все данные хранятся на устройстве. Очистка данных миниаппы, переустановка Telegram или смена телефона могут привести к их потере.</p><p class="sheet-description">Сохраняй копию после закупок и маркетов.</p><div class="info-foot">Храни файл в «Файлах» или на своём диске, вне кэша Telegram. Экспорт: Настройки → Резервная копия.</div><div class="sheet-footer backup-notice-actions"><button class="button" data-action="ack-backup-notice">Понятно</button><button class="button secondary" data-action="open-backups">К резервным копиям</button></div>`);}
function goalInfo(value){const copies={market:'Цель — выручка на сумму стола и доп. расходов. Закупка может окупиться частично. Цены не ниже себестоимости.',all:'Цель — вернуть расходы на участие и закупку только взятого на маркет мерча.',plus:'К расходам на участие и закупке взятого мерча добавляем заданный процент. Вложения 10 000 ₽ и +25% → цель 12 500 ₽.'};info(goalNames[value],copies[value]);}
function metricsInfo(){info('Как считаем','<strong>Выручка</strong> — сумма продаж товаров и наборов.<br><br><strong>После всех вложений</strong> — выручка − участие − закупка всего взятого мерча.<br><br><strong>Прибыль с проданного</strong> — выручка − участие − себестоимость проданного. Остатки остаются запасом.<br><br>Простой режим: цены пропорциональны себестоимости и округлены вверх. Товары без затрат получают одинаковый вес.','План и факт считаются отдельно. Для полок учитываем записанную аренду и комиссию.');}

function itemForm(id=null,addToCalc=false){const old=state.inventory.find(i=>i.id===id);const item=old||{name:'',category:'Брелок',qty:1,cost:0,price:0};const form=openForm(old?'Редактировать мерч':'Новый мерч',`${selectField('Вид','category',categories,item.category)}${field('Название','name',item.name,'text','required maxlength="120" placeholder="Брелок «Звезда»"')}<div class="form-grid">${old?'':field('В наличии, шт.','qty',item.qty,'number','required min="1" max="10000000" step="1"')}${field('Себестоимость, ₽/шт.','cost',item.cost,'number',`required min="0" max="1000000000" step="0.01" ${old?'disabled':''}`,old?'Меняется через «Добавить».':'')}${field('Цена продажи, ₽/шт.','price',item.price,'number','required min="0" max="1000000000" step="0.01"','Можно изменить для маркета.')}</div><label class="file-label">${icon('camera',20)} <span>${old?.photo?'Заменить фото':'Добавить фото'}<br><small>Необязательно · сожмём локально</small></span><input name="photo" type="file" accept="image/*"></label><p class="filename" id="photo-name"></p>`,old?'Сохранить':'Добавить мерч',async f=>{let photo=old?.photo||false;const file=f.elements.photo.files[0];if(file){const blob=await compressPhoto(file);photo=uid();await storePhoto(photo,blob);}const newId=old?.id||uid();await commit(next=>{if(old){Object.assign(next.inventory.find(i=>i.id===id),{name:f.elements.name.value.trim(),category:f.elements.category.value,price:formNum(f,'price'),photo});}else{const qty=formNum(f,'qty');if(!Number.isInteger(qty)||qty<1)throw new Error('Количество — целое, от 1.');const cost=roundMoney(formNum(f,'cost'));next.inventory.push({id:newId,name:f.elements.name.value.trim(),category:f.elements.category.value,qty,cost,price:formNum(f,'price'),photo,color:['red','blue','lavender'][next.inventory.length%3]});next.activity.push({id:uid(),date:today(),kind:'purchase',itemId:newId,qty,cost});}if(addToCalc)addLine(next,newId);},old?'Товар обновлён':'Мерч добавлен');closeSheet();});progressiveForm(form,['Товар','Количество и цены','Фото'],[[0,1],[2],[3,4]]);form.elements.photo.addEventListener('change',()=>{sheet.querySelector('#photo-name').textContent=form.elements.photo.files[0]?.name||'';});}
function itemMenu(id){const item=state.inventory.find(i=>i.id===id);setSheet(esc(item.name),`${thumb(item)}<div class="detail-stats">${stat('В наличии',`${item.qty} шт.`)}${stat('Свободно',`${freeStock(id)} шт.`)}${stat('Себестоимость / шт.',money(item.cost))}${stat('Обычная цена',money(item.price))}</div><div class="settings-actions"><button class="button" data-action="add-to-plan" data-id="${esc(id)}" ${freeStock(id)?'':'disabled'}>${icon('plus',16)} В расчёт</button><button class="button secondary" data-action="restock" data-id="${esc(id)}">${icon('box',16)} Добавить</button><button class="button secondary" data-action="edit-item" data-id="${esc(id)}">${icon('edit',16)} Изменить товар</button><button class="text-btn" data-action="writeoff" data-id="${esc(id)}">Списать</button><button class="text-btn" data-action="delete-item" data-id="${esc(id)}">${icon('trash',16)} Удалить товар</button></div>`);}
function restockForm(id){const item=state.inventory.find(i=>i.id===id);openForm('Добавить мерч',`<p class="sheet-description">${esc(item.name)}. ${item.qty} шт. · ${money(item.cost)}/шт. Закупка пересчитает среднюю себестоимость.</p><div class="form-grid">${field('Добавить, шт.','qty',1,'number','required min="1" max="10000000" step="1"')}${field('Себестоимость, ₽/шт.','cost',item.cost,'number','required min="0" max="1000000000" step="0.01"')}</div>`, 'Добавить',async f=>{await commit(next=>addStock(next,id,formNum(f,'qty'),formNum(f,'cost')),'Закупка добавлена');closeSheet();});}
function writeoffForm(id){const item=state.inventory.find(i=>i.id===id),max=freeStock(id);openForm('Списать',`<p class="sheet-description">${esc(item.name)} · свободно ${max} шт. Списать можно только свободный мерч.</p>${field('Списать, шт.','qty',1,'number',`required min="1" max="${max}" step="1"`)}${field('Причина','reason','','text','required maxlength="120" placeholder="Брак"')}`,'Списать',async f=>{await commit(next=>{const qty=formNum(f,'qty');if(!Number.isInteger(qty)||qty<1||qty>available(next,id))throw new Error('Недостаточно свободного мерча.');next.inventory.find(i=>i.id===id).qty-=qty;next.activity.push({id:uid(),date:today(),kind:'writeoff',itemId:id,qty,reason:f.elements.reason.value.trim()});},'Списание записано');closeSheet();});}
function addLine(next,id,qty=1){const item=next.inventory.find(i=>i.id===id);const existing=next.draft.lines.find(l=>l.itemId===id),free=available(next,id,next.editingId);if(!item||free<1)throw new Error('Нет свободного мерча.');if(existing){if(existing.qty+qty>free)throw new Error(`Доступно всего ${free} шт.`);existing.qty+=qty;}else{next.draft.lines.push({itemId:item.id,name:item.name,category:item.category,cost:item.cost,price:item.price,qty:Math.min(qty,free),photo:item.photo,color:item.color});}}
function pickItem(){
 const items=state.inventory.filter(i=>!i.archived&&freeStock(i.id,state.editingId)>0);
 const form=openForm('Мерч на маркет',`<p class="sheet-description">Выбери количество каждого товара.</p>${items.map(i=>{const qty=state.draft.lines.find(l=>l.itemId===i.id)?.qty||0;return `<label class="sale-line"><span>${esc(i.name)}<small>Свободно ${freeStock(i.id,state.editingId)} шт.</small></span><input name="pick-${esc(i.id)}" aria-label="Взять: ${esc(i.name)}" type="number" inputmode="numeric" min="0" max="${freeStock(i.id,state.editingId)}" step="1" value="${qty}"></label>`;}).join('')||'<p class="sheet-description">Нет свободного мерча.</p>'}<button type="button" class="text-btn" data-action="new-item-calc">${icon('plus',16)} Новый товар</button>`,'Готово',async f=>{await commit(next=>{for(const item of items){const qty=formNum(f,'pick-'+item.id),line=next.draft.lines.find(l=>l.itemId===item.id);if(line)line.qty=qty;else if(qty>0)addLine(next,item.id,qty);}next.draft.lines=next.draft.lines.filter(l=>l.qty>0&&!next.inventory.find(i=>i.id===l.itemId)?.archived);next.draft.promos=next.draft.promos.filter(p=>p.parts.every(part=>next.draft.lines.some(l=>l.itemId===part.itemId)));});closeSheet();});
}
function expenseForm(){openForm('Добавить расход',`${field('Название','name','','text','required maxlength="120" list="expense-presets" placeholder="Впиши название"')}<datalist id="expense-presets">${['Дорога','Оформление','Проживание','Упаковка','Помощник','Печать ценников'].map(x=>`<option value="${x}">`).join('')}</datalist>${field('Сумма, ₽','amount','','number','required min="0" max="1000000000" step="0.01"')}`,'Добавить расход',async f=>{await commit(next=>next.draft.expenses.push({id:uid(),name:f.elements.name.value.trim(),amount:formNum(f,'amount')}));closeSheet();});}
function promoForm(id=null){if(!state.draft.lines.length)return toast('Сначала добавь товары в расчёт.');const existing=state.draft.promos.find(p=>p.id===id);let parts=clone(existing?.parts||[{itemId:state.draft.lines[0].itemId,qty:2}]);const partHTML=()=>parts.map((p,i)=>`<div class="promo-part"><select aria-label="Товар в наборе ${i+1}" data-part-item="${i}">${state.draft.lines.map(l=>`<option value="${esc(l.itemId)}" ${p.itemId===l.itemId?'selected':''}>${esc(l.name)}</option>`).join('')}</select><input aria-label="Количество товара в наборе ${i+1}" type="number" min="1" max="10000000" step="1" value="${p.qty}" data-part-qty="${i}"><button type="button" data-remove-part="${i}" aria-label="Убрать позицию из набора">${icon('close',15)}</button></div>`).join('');const form=openForm(existing?'Редактировать акцию':'Собрать набор',`${field('Название акции','name',existing?.name||'Новый набор','text','required maxlength="120"')}<p class="small muted" style="margin-bottom:12px">До 10 позиций. Для одинаковых товаров укажи количество.</p><div id="promo-parts">${partHTML()}</div><button type="button" class="text-btn" id="add-part">${icon('plus',14)} Ещё позиция</button><div class="form-grid">${field('Цена набора, ₽','price',existing?.price||0,'number','required min="0" max="1000000000" step="0.01"')}${field('Продам, наборов','count',existing?.count||0,'number','required min="0" max="10000000" step="1"')}</div><div class="info-foot" id="promo-capacity"></div>${existing?`<button type="button" class="text-btn" data-action="delete-promo" data-id="${esc(id)}">Удалить акцию</button>`:''}`,'Сохранить набор',async f=>{for(const part of parts){if(!Number.isInteger(part.qty)||part.qty<1)throw new Error('Количество в наборе — целое, от 1.');}parts=mergeParts(parts);if(!parts.length)throw new Error('Добавь хотя бы одну позицию.');const trial=clone(state.draft);const promo={id:id||uid(),name:f.elements.name.value.trim(),parts,price:formNum(f,'price'),count:formNum(f,'count')};const index=trial.promos.findIndex(p=>p.id===id);if(index<0)trial.promos.push(promo);else trial.promos[index]=promo;const limits=bundleLimits(trial,promo);if(promo.count>limits.forecast)throw new Error(`По прогнозу доступно ${limits.forecast} наборов. Уменьши число или увеличь процент продаж на шаге «Акции».`);await commit(next=>{next.draft.promos=trial.promos;});closeSheet();});const updateCap=()=>{const limits=bundleLimits(state.draft,{id,parts:mergeParts(parts)});sheet.querySelector('#promo-capacity').textContent=`Из взятого мерча: ${limits.stock} наборов. По прогнозу ${state.draft.sellPercent}%: ${limits.forecast} (с учётом предыдущих акций).`;form.elements.count.max=limits.forecast;};form.addEventListener('input',e=>{if(e.target.dataset.partItem!==undefined)parts[Number(e.target.dataset.partItem)].itemId=e.target.value;if(e.target.dataset.partQty!==undefined)parts[Number(e.target.dataset.partQty)].qty=Number(e.target.value);updateCap();});form.addEventListener('click',e=>{const remove=e.target.closest('[data-remove-part]');if(remove){parts.splice(Number(remove.dataset.removePart),1);sheet.querySelector('#promo-parts').innerHTML=partHTML();updateCap();}});sheet.querySelector('#add-part').onclick=()=>{if(parts.length>=10)return toast('В наборе максимум 10 позиций.');parts.push({itemId:state.draft.lines.find(l=>!parts.some(p=>p.itemId===l.itemId))?.itemId||state.draft.lines[0].itemId,qty:1});sheet.querySelector('#promo-parts').innerHTML=partHTML();updateCap();};updateCap();}
function eventForm(){if(!state.draft.lines.length)return toast('Добавь мерч в расчёт.');const existing=state.events.find(e=>e.id===state.editingId),p=projection(state.draft);openForm(existing?'Обновить план':'Сохранить маркет',`${field('Название маркета','name',existing?.name||'','text','required maxlength="120" placeholder="Осенний артмаркет"')}${field('Дата','date',existing?.date||'','date')}${field('Место / адрес','address',existing?.address||'','text','maxlength="500" placeholder="Город, площадка, номер стола"')}<div class="info-foot">${p.total} шт. мерча · ${p.lines.length} поз.<br>Прогноз выручки: <strong>${money(p.revenue)}</strong><br>Цены и себестоимость зафиксируются. Мерч зарезервируется за маркетом.</div>${p.shortfall>0&&state.draft.mode==='simple'?`<div class="notice">До цели не хватает ${money(p.shortfall)}.</div>`:''}`,'Сохранить план',async f=>{await commit(next=>saveEvent(next,next.draft,{name:f.elements.name.value,date:f.elements.date.value,address:f.elements.address.value}),'План сохранён, мерч зарезервирован');closeSheet();view='places';placesTab='markets';render();window.scrollTo({top:0});});}
function eventDetail(id){const e=state.events.find(x=>x.id===id),p=projection(e.plan),sold=soldCounts(e),revenue=e.sales.reduce((n,s)=>n+s.revenue,0),cogs=e.sales.reduce((n,s)=>n+s.cogs,0);setSheet(esc(e.name),`<p class="sheet-description">${dateText(e.date)}${e.address?` · ${esc(e.address)}`:''}</p><div class="detail-stats">${stat('Выручка по факту',money(revenue))}${stat('Все вложения',money(p.costs+p.procurement))}${stat('После всех вложений',money(revenue-p.costs-p.procurement),revenue-p.costs-p.procurement>=0?'positive':'negative')}${stat('Прибыль с проданного',money(revenue-cogs-p.costs),revenue-cogs-p.costs>=0?'positive':'negative')}</div><div class="inline-actions">${e.status!=='completed'?`<button class="button compact" data-action="event-sale" data-id="${esc(id)}">${icon('plus',14)} Внести продажи</button><button class="button secondary compact" data-action="finish-event" data-id="${esc(id)}">Завершить маркет</button>`:`<span class="badge done">${icon('check',12)} Завершён · остатки свободны</span><button class="text-btn" data-action="reopen-event" data-id="${esc(id)}">Открыть снова</button>`}${e.status==='planned'&&!e.sales.length?`<button class="button secondary compact" data-action="edit-event" data-id="${esc(id)}">${icon('edit',13)} Изменить план</button>`:''}<button class="text-btn" data-action="copy-event" data-id="${esc(id)}">${icon('copy',13)} Повторить</button><button class="text-btn" data-action="event-meta" data-id="${esc(id)}">Данные маркета</button></div><div class="detail-title">Мерч и цены <span class="muted small">продано / взято</span></div>${e.plan.lines.map(l=>`<div class="detail-row"><div class="detail-row-main">${thumb(l)}<span><strong>${esc(l.name)}</strong><small>${money(l.price)} / шт. · закупка ${money(l.cost)}</small></span></div><strong>${sold[l.itemId]||0} / ${l.qty}</strong></div>`).join('')}${e.plan.promos.length?`<div class="detail-title">Акции</div>${e.plan.promos.map(b=>`<div class="detail-row"><span>${esc(b.name)}</span><strong>${money(b.price)}</strong></div>`).join('')}`:''}<div class="detail-title">Расходы</div><div class="detail-row"><span>Место / стол</span><strong>${money(e.plan.table)}</strong></div>${e.plan.expenses.map(x=>`<div class="detail-row"><span>${esc(x.name)}</span><strong>${money(x.amount)}</strong></div>`).join('')}<div class="detail-title">Чеклист <button class="text-btn" data-action="add-check" data-id="${esc(id)}">${icon('plus',13)} Пункт</button></div>${e.checklist.map(c=>`<div class="checklist-row ${c.done?'checked':''}"><button data-action="toggle-check" data-id="${esc(id)}" data-check="${esc(c.id)}" aria-label="${c.done?'Снять отметку':'Отметить'}: ${esc(c.text)}" aria-pressed="${c.done}">${c.done?icon('check',14):''}</button><span>${esc(c.text)}</span></div>`).join('')}<div class="detail-title">История продаж ${e.sales.length&&e.status!=='completed'?`<button class="text-btn" data-action="undo-event-sale" data-id="${esc(id)}">Отменить последнюю</button>`:''}</div>${history(e.sales)||'<p class="small muted">Продаж пока нет. Прогноз выручки — '+money(p.revenue)+'.</p>'}<div class="section-divider"></div><button class="text-btn" data-action="delete-event" data-id="${esc(id)}">${icon('trash',16)} Удалить маркет</button>`);detailPages('event-'+id,['Обзор','План','Продажи'],[['Мерч и цены',1],['История продаж',2]]);}
function history(sales){return [...sales].reverse().map(s=>`<div class="history-row"><div class="history-top"><strong>${money(s.revenue)}</strong><span class="muted">${fmtDate(s.date)}</span></div><p>${s.details.map(d=>`${esc(d.name)} × ${d.qty}`).join(' · ')}</p></div>`).join('');}
function saleForm(id,shelfMode=false,finish=false){
 const place=(shelfMode?state.shelves:state.events).find(p=>p.id===id);
 const sold=shelfMode?{}:soldCounts(place);
 const plan=shelfMode?{lines:Object.keys(place.stock).filter(k=>place.stock[k]>0).map(itemId=>{const item=state.inventory.find(i=>i.id===itemId);return {itemId,name:item.name,price:place.prices[itemId],cost:place.costs[itemId]};}),promos:[]}:place.plan;
 const remaining=shelfMode?place.stock:Object.fromEntries(plan.lines.map(l=>[l.itemId,l.qty-(sold[l.itemId]||0)]));
 let step=0,quantities={},revenue=null,date=today();
 const estimate=()=>plan.lines.reduce((n,l)=>n+(quantities[l.itemId]||0)*l.price,0);
 const units=()=>Object.values(quantities).reduce((n,q)=>n+q,0);
 const draw=()=>{
 const content=step===0?`<p class="sheet-description">Новые продажи, включая товары из наборов. Уже записанные продажи не добавляй.</p>${plan.lines.map(l=>`<label class="sale-line"><span>${esc(l.name)}<small>Осталось ${remaining[l.itemId]||0} шт.</small></span><input name="qty-${esc(l.itemId)}" aria-label="Продано: ${esc(l.name)}" type="number" inputmode="numeric" min="0" max="${remaining[l.itemId]||0}" step="1" value="${quantities[l.itemId]||0}"></label>`).join('')}`:step===1?`<p class="sheet-description">За ${units()} шт. по обычным ценам — ${money(estimate())}. Если были акции или скидки, укажи фактическую сумму.</p>${field('Выручка за эти продажи, ₽','revenue',revenue??estimate(),'number','required min="0" max="1000000000" step="0.01"')}${field('Дата продаж','date',date,'date','required')}`:`<div class="detail-stats">${stat('Продано',units()+' шт.')}${stat('Выручка',money(revenue||0))}</div>${plan.lines.filter(l=>quantities[l.itemId]>0).map(l=>`<div class="detail-row"><span>${esc(l.name)}</span><strong>${quantities[l.itemId]} шт.</strong></div>`).join('')}<p class="sheet-description">${finish?'Маркет завершится. Непроданный мерч станет свободным.':'Продажи спишутся из остатков.'}</p>`;
 const form=openForm(`${step+1} из 3 · ${['Проданный мерч','Выручка','Проверка'][step]}`,content,step<2?'Далее':finish?'Завершить маркет':'Записать продажи',async f=>{
 if(step===0){const previousEstimate=estimate();quantities=Object.fromEntries(plan.lines.map(l=>[l.itemId,formNum(f,'qty-'+l.itemId)]));if(revenue===previousEstimate)revenue=null;if(!units())revenue=0;if(!units()&&!finish)throw new Error('Укажи количество проданного.');if(units())makeSale(plan,remaining,quantities,{});step=units()?1:2;draw();return;}
 if(step===1){revenue=formNum(f,'revenue');date=f.elements.date.value;step=2;draw();return;}
 await commit(next=>{if(shelfMode){sellShelf(next,id,quantities,revenue);next.shelves.find(s=>s.id===id).sales.at(-1).date=date;}else{const event=next.events.find(e=>e.id===id),before=event.sales.length;sellEvent(next,id,quantities,{},revenue,finish);if(event.sales.length>before)event.sales.at(-1).date=date;}},finish?'Маркет завершён':'Продажи записаны');shelfMode?shelfDetail(id):eventDetail(id);
 });
 if(step){const back=document.createElement('button');back.type='button';back.className='button secondary';back.textContent='Назад';back.onclick=()=>{if(step===1){revenue=formNum(form,'revenue');date=form.elements.date.value;}step=step===2&&!units()?0:step-1;draw();};form.querySelector('.sheet-footer').prepend(back);}
 };draw();
}
function collectSale(form,plan){return {quantities:Object.fromEntries(plan.lines.map(l=>[l.itemId,formNum(form,'qty-'+l.itemId)])),bundles:Object.fromEntries(plan.promos.map(b=>[b.id,formNum(form,'bundle-'+b.id)]))};}
function eventMeta(id){const e=state.events.find(x=>x.id===id);openForm('Данные маркета',`${field('Название','name',e.name,'text','required maxlength="120"')}${field('Дата','date',e.date,'date')}${field('Место / адрес','address',e.address,'text','maxlength="500"')}`,'Сохранить',async f=>{await commit(next=>Object.assign(next.events.find(x=>x.id===id),{name:f.elements.name.value.trim(),date:f.elements.date.value,address:f.elements.address.value.trim()}));eventDetail(id);});}

function shelfForm(id=null){const old=state.shelves.find(s=>s.id===id),s=old||{name:'',address:'',rent:0,commission:0,interval:14,nextCheck:dayPlus(today(),14),nextRent:today()};const form=openForm(old?'Настройки полки':'Новая полка',`${field('Название','name',s.name,'text','required maxlength="120" placeholder="Полка чудес"')}${field('Адрес / место','address',s.address,'text','maxlength="500"')}<div class="form-grid">${field('Аренда в месяц, ₽','rent',s.rent,'number','required min="0" max="1000000000" step="0.01"')}${field('Комиссия, %','commission',s.commission,'number','required min="0" max="100" step="0.1"')}${field('Следующая оплата','nextRent',s.nextRent,'date')}${field('Проверять раз в, дн.','interval',s.interval,'number','required min="1" max="365" step="1"')}${field('Следующая проверка','nextCheck',s.nextCheck,'date')}</div><div class="info-foot">Аренда попадёт в расходы по кнопке «Записать оплату».</div>`,old?'Сохранить':'Создать полку',async f=>{const newId=id||uid();await commit(next=>{const fields={name:f.elements.name.value.trim(),address:f.elements.address.value.trim(),rent:formNum(f,'rent'),commission:formNum(f,'commission'),interval:formNum(f,'interval'),nextCheck:f.elements.nextCheck.value,nextRent:f.elements.nextRent.value};if(old)Object.assign(next.shelves.find(x=>x.id===id),fields);else next.shelves.push({id:newId,...fields,stock:{},prices:{},costs:{},targets:{},sales:[],payments:[],movements:[]});},old?'Полка обновлена':'Полка создана');shelfDetail(newId);});const grid=form.querySelector('.form-grid');const dates=document.createElement('div');dates.className='form-grid';for(const node of [...grid.children].slice(2))dates.append(node);grid.after(dates);progressiveForm(form,['Полка','Аренда','Даты'],[[0,1],[2],[3,4]]);}
function shelfDetail(id){const s=state.shelves.find(x=>x.id===id),r=shelfReport(s,reportMonth);setSheet(esc(s.name),`<p class="sheet-description">${esc(s.address||'Без адреса')}<br>${money(s.rent)} / месяц${s.commission?` · комиссия ${s.commission}%`:''}</p><div class="inline-actions"><button class="button compact" data-action="shelf-transfer" data-id="${esc(id)}">${icon('plus',14)} Завезти мерч</button><button class="button secondary compact" data-action="shelf-sale" data-id="${esc(id)}" ${Object.values(s.stock).some(q=>q>0)?'':'disabled'}>Внести продажи</button><button class="text-btn" data-action="edit-shelf" data-id="${esc(id)}">Настройки</button></div><div class="report-toolbar"><span>Отчёт за месяц</span><input type="month" id="report-month" data-id="${esc(id)}" aria-label="Месяц отчёта полки" value="${reportMonth}"></div><div class="detail-stats">${stat('Выручка',money(r.revenue))}${stat('Прибыль',money(r.profit),r.profit>=0?'positive':'negative')}${stat('Оплаченная аренда',money(r.rent))}${stat('Комиссия',money(r.commission))}</div>${!r.rent&&s.rent>0?'<div class="notice">Оплата аренды за месяц не записана и в расходы не включена.</div>':''}<div class="detail-title">Мерч на полке <button class="text-btn" data-action="shelf-transfer" data-id="${esc(id)}" data-return="1">Забрать домой</button></div>${Object.keys(s.stock).map(itemId=>{const item=state.inventory.find(i=>i.id===itemId),needed=Math.max(0,(s.targets[itemId]||0)-s.stock[itemId]);return `<div class="detail-row"><div class="detail-row-main">${thumb(item)}<span><strong>${esc(item.name)}</strong><small>${money(s.prices[itemId])} / шт. ${needed?`· довезти ${needed} шт.`:''}</small></span></div><button class="text-btn" data-action="shelf-item" data-id="${esc(id)}" data-item="${esc(itemId)}">${s.stock[itemId]} шт. ${icon('edit',12)}</button></div>`;}).join('')||'<p class="small muted">Добавь мерч из инвентаря.</p>'}<div class="detail-title">Проверки и аренда</div><div class="detail-row"><span>Проверить остатки<small class="muted" style="display:block;margin-top:4px">${s.nextCheck?dateText(s.nextCheck):'Дата не задана'} · раз в ${s.interval} дн.</small></span><button class="text-btn" data-action="checked-shelf" data-id="${esc(id)}">Проверено ${icon('check',13)}</button></div><div class="detail-row"><span>Следующая аренда<small class="muted" style="display:block;margin-top:4px">${s.nextRent?dateText(s.nextRent):'Дата не задана'}</small></span><button class="text-btn" data-action="pay-rent" data-id="${esc(id)}">Записать оплату</button></div><div class="detail-title">Продажи за ${esc(reportMonth)} ${s.sales.length?`<button class="text-btn" data-action="undo-shelf-sale" data-id="${esc(id)}">Отменить последнюю</button>`:''}</div>${history(s.sales.filter(x=>x.date.startsWith(reportMonth)))||'<p class="small muted">За месяц продаж нет.</p>'}${s.payments.length?`<div class="detail-title">Платежи за аренду</div>${s.payments.filter(p=>p.date.startsWith(reportMonth)).map(p=>`<div class="detail-row"><span>${fmtDate(p.date)}</span><strong>${money(p.amount)}</strong><button class="info-button" data-action="undo-rent" data-id="${esc(id)}" data-payment="${esc(p.id)}" aria-label="Отменить платёж ${money(p.amount)}">${icon('undo',14)}</button></div>`).join('')}`:''}`);detailPages('shelf-'+id,['Мерч','Отчёт','Аренда'],[['Отчёт за месяц',1],['Мерч на полке',0],['Проверки и аренда',2],['Продажи за',1],['Платежи за аренду',2]]);}
function shelfTransferForm(id,returning=false){const shelf=state.shelves.find(s=>s.id===id),items=state.inventory.filter(i=>!i.archived&&(returning?(shelf.stock[i.id]||0):freeStock(i.id))>0);if(!items.length)return toast(returning?'На полке пока нет мерча.':'Свободных товаров пока нет.');const getMax=itemId=>returning?(shelf.stock[itemId]||0):freeStock(itemId);const form=openForm(returning?'Забрать мерч с полки':'Пополнить полку',`${selectField('Товар','itemId',items.map(i=>[i.id,i.name]),items[0].id)}${field('Количество, шт.','qty',1,'number',`required min="1" max="${getMax(items[0].id)}" step="1"`)}<p class="small muted" id="transfer-max">Доступно ${getMax(items[0].id)} шт.</p>` ,returning?'Забрать с полки':'Завезти на полку',async f=>{await commit(next=>transferShelf(next,id,f.elements.itemId.value,formNum(f,'qty'),returning),returning?'Мерч снова доступен':'Мерч размещён на полке');shelfDetail(id);});form.elements.itemId.addEventListener('change',()=>{const max=getMax(form.elements.itemId.value);form.elements.qty.max=max;sheet.querySelector('#transfer-max').textContent=`Доступно ${max} шт.`;});}
function shelfItemForm(id,itemId){const shelf=state.shelves.find(s=>s.id===id),item=state.inventory.find(i=>i.id===itemId);openForm(esc(item.name),`${field('Цена на полке, ₽/шт.','price',shelf.prices[itemId],'number','required min="0" max="1000000000" step="0.01"')}${field('Целевой запас, шт.','target',shelf.targets[itemId]||0,'number','required min="0" max="10000000" step="1"','Подскажем, сколько довезти.')}`,'Сохранить',async f=>{await commit(next=>{const s=next.shelves.find(x=>x.id===id);s.prices[itemId]=formNum(f,'price');s.targets[itemId]=formNum(f,'target');});shelfDetail(id);});}
function rentForm(id){const s=state.shelves.find(x=>x.id===id);openForm('Записать оплату аренды',`${field('Сумма, ₽','amount',s.rent,'number','required min="0" max="1000000000" step="0.01"')}${field('Дата оплаты','date',today(),'date','required')}<div class="info-foot">Расход — в месяце оплаты. Следующая оплата — через месяц от этой даты.</div>`,'Записать платёж',async f=>{await commit(next=>{const shelf=next.shelves.find(x=>x.id===id),date=f.elements.date.value;shelf.payments.push({id:uid(),date,amount:formNum(f,'amount'),previousNextRent:shelf.nextRent});shelf.nextRent=nextMonth(date);},'Оплаченная аренда');reportMonth=f.elements.date.value.slice(0,7);shelfDetail(id);});}

async function exportBackup(){toast('Готовим резервную копию…');const snapshot=clone(state),referenced=new Set([...snapshot.inventory.map(i=>i.photo),...snapshot.events.flatMap(e=>e.plan.lines.map(l=>l.photo)),...snapshot.draft.lines.map(l=>l.photo)].filter(Boolean));const photos=[];for(const [id,blob]of (isDemo?[...demoPhotos].filter(([id])=>referenced.has(id)):await getPhotos([...referenced])))if(referenced.has(id))photos.push({id,data:await blobDataURL(blob)});const blob=new Blob([JSON.stringify({app:'solyanka',version:1,createdAt:new Date().toISOString(),state:snapshot,photos})],{type:'application/json'}),name=`solyanka-${today()}.json`,url=URL.createObjectURL(blob);setSheet('Копия готова',`<p class="sheet-description">Мерч: ${snapshot.inventory.length} · маркеты: ${snapshot.events.length}<br>Полки: ${snapshot.shelves.length} · фото: ${photos.length}<br>Размер: ${(blob.size/1024).toFixed(0)} КБ.</p><a class="button full" id="backup-link" href="${url}" download="${name}">${icon('download',16)} Скачать копию</a><div id="share-backup"></div><p class="small muted" style="margin-top:15px">Сохрани файл вне кэша Telegram.</p>`);const file=new File([blob],name,{type:'application/json'});if(navigator.canShare?.({files:[file]})){const button=document.createElement('button');button.className='button secondary full';button.style.marginTop='10px';button.textContent='Поделиться файлом';button.onclick=()=>navigator.share({files:[file],title:'Резервная копия Солянки'}).catch(e=>{if(e.name!=='AbortError')toast('Не удалось поделиться. Скачай копию.');});sheet.querySelector('#share-backup').append(button);}sheet.addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
function importBackup(){setSheet('Восстановить данные',`<p class="sheet-description">Выбери копию Солянки (.json). Проверим файл перед восстановлением.</p><label class="file-label">${icon('file',23)} Выбрать копию<input id="backup-file" type="file" accept=".json,application/json"></label><div class="form-error" id="import-error" role="alert"></div>`);sheet.querySelector('#backup-file').addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>40*1024*1024)throw new Error('Копия должна быть до 40 МБ.');const data=JSON.parse(await file.text());if(data.app!=='solyanka'||data.version!==1||!Array.isArray(data.photos))throw new Error('Выбери резервную копию Солянки версии 1.');validateState(data.state);for(const photo of data.photos)if(typeof photo.id!=='string'||photo.id.length>100||typeof photo.data!=='string'||photo.data.length>4e6||!/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(photo.data))throw new Error('В копии повреждено фото.');openForm('Восстановить эту копию?',`<p class="sheet-description">В файле: мерч ${data.state.inventory.length}, маркеты ${data.state.events.length}, полки ${data.state.shelves.length}, фото ${data.photos.length}.</p><div class="notice">Копия заменит все текущие данные. При необходимости сначала сохрани их.</div><label class="check-field"><input type="checkbox" required> Заменить текущие данные</label>`,'Восстановить данные',async()=>{clearTimeout(saveTimer);const restored=clone(data.state),mapping=new Map();restored.settings.backupNoticeSeen=state.settings.backupNoticeSeen===true;for(const photo of data.photos){const newid=uid(),parts=photo.data.split(','),binary=atob(parts[1]),bytes=Uint8Array.from(binary,c=>c.charCodeAt(0)),blob=new Blob([bytes],{type:parts[0].split(':')[1].split(';')[0]});await storePhoto(newid,blob);mapping.set(photo.id,newid);}for(const item of restored.inventory)if(item.photo)item.photo=mapping.get(item.photo)||false;for(const line of [...restored.draft.lines,...restored.events.flatMap(e=>e.plan.lines)])if(line.photo)line.photo=mapping.get(line.photo)||false;restored.updatedAt=Date.now();if(!isDemo)await saveState(restored);clearTimeout(saveTimer);state=restored;storageReadOnly=false;closeSheet();navigate('inventory');toast('Данные восстановлены');});}catch(err){const el=sheet.querySelector('#import-error');if(el)el.textContent=err.message;else toast(err.message);}});}

document.addEventListener('click',async e=>{const button=e.target.closest('[data-action]');if(!button||button.disabled||busy)return;const {action,id,value}=button.dataset;try{switch(action){
  case 'nav':navigate(button.dataset.view);break;
  case 'calc-step':if(Number(value)>0&&!state.draft.lines.length)break;state.draft.uiStep=Number(value);persistDraft();navigate('calc');break;
  case 'toggle-settings':if(view==='settings')navigate(settingsReturn.view,settingsReturn.scroll);else navigate('settings');break;
  case 'theme-toggle':state.settings.theme=document.documentElement.dataset.theme==='dark'?'light':'dark';persistDraft();render();break;
  case 'theme':state.settings.theme=value;persistDraft();render();break;
  case 'close-sheet':closeSheet();break;
  case 'demo':location.href=location.pathname+'?demo=1';break;
  case 'exit-demo':location.href=location.pathname;break;
  case 'goal-info':goalInfo(value);break;
  case 'metrics-info':metricsInfo();break;
    case 'mode':if(value==='pro'&&state.draft.mode==='simple'){const p=projection(state.draft);for(const l of state.draft.lines)l.price=p.lines.find(x=>x.itemId===l.itemId).price;for(const b of state.draft.promos){const computed=p.bundles.find(x=>x.id===b.id);b.price=computed.price;b.count=computed.count;}}state.draft.mode=value;persistDraft();render();haptic();break;
  case 'goal':state.draft.goal=value;persistDraft();render();haptic();break;
  case 'new-item':itemForm();break;
  case 'new-item-calc':itemForm(null,true);break;
  case 'edit-item':itemForm(id);break;
  case 'item-menu':itemMenu(id);break;
  case 'restock':restockForm(id);break;
  case 'writeoff':writeoffForm(id);break;
  case 'delete-item':{const item=state.inventory.find(i=>i.id===id);if(freeStock(id)!==item.qty){info('Товар занят','Сначала освободи мерч с активных маркетов и полок.','После этого товар можно удалить.');break;}openForm('Удалить товар?',`<p class="sheet-description">${esc(item.name)} исчезнет из инвентаря и черновика. Его остаток (${item.qty} шт.) будет списан. История продаж сохранится.</p>`,'Удалить товар',async()=>{await commit(next=>deleteItem(next,id),'Товар удалён');closeSheet();});break;}
  case 'delete-event':openForm('Удалить маркет?','<p class="sheet-description">План и отчёт удалятся. Непроданный мерч станет доступен, проданный останется списанным.</p>','Удалить маркет',async()=>{await commit(next=>deleteEvent(next,id),'Маркет удалён');closeSheet();});break;
  case 'pick-item':pickItem();break;
  case 'add-to-plan':await commit(next=>addLine(next,id),'Товар добавлен в расчёт');if(sheet.open)closeSheet();break;
  case 'pick-line':{const item=state.inventory.find(i=>i.id===id),free=freeStock(id,state.editingId),old=state.draft.lines.find(l=>l.itemId===id);openForm(esc(item.name),`${field('Беру на маркет, шт.','qty',Math.min(free-(old?.qty||0),10),'number',`required min="1" max="${free-(old?.qty||0)}" step="1"`)}<div class="info-foot">Свободно ${free} шт.${old?` В расчёт уже добавлено ${old.qty} шт.`:''}</div>`,'В расчёт',async f=>{await commit(next=>addLine(next,id,formNum(f,'qty')));closeSheet();});break;}
  case 'remove-line':{const affected=state.draft.promos.filter(p=>p.parts.some(x=>x.itemId===id)).length;await commit(next=>{next.draft.lines=next.draft.lines.filter(l=>l.itemId!==id);next.draft.promos=next.draft.promos.filter(p=>!p.parts.some(x=>x.itemId===id));});if(affected)toast('Связанные наборы удалены из расчёта');break;}
  case 'add-expense':expenseForm();break;
  case 'remove-expense':await commit(next=>{next.draft.expenses=next.draft.expenses.filter(x=>x.id!==id);});break;
  case 'promo':promoForm(id);break;
  case 'delete-promo':await commit(next=>{next.draft.promos=next.draft.promos.filter(x=>x.id!==id);});closeSheet();break;
  case 'save-event':eventForm();break;
  case 'reset-draft':openForm('Очистить расчёт?','<p class="sheet-description">Черновик очистится. Инвентарь и маркеты сохранятся.</p>','Новый расчёт',async()=>{await commit(next=>{next.draft=blankPlan();next.editingId=null;});closeSheet();});break;
  case 'places-tab':placesTab=value;render();break;
  case 'event-filter':eventFilter=value;render();break;
  case 'new-market':if(state.editingId){openForm('Новый расчёт','<p class="sheet-description">Текущий черновик заменится новым. Сохранённый маркет останется.</p>','Новый расчёт',async()=>{await commit(next=>{next.draft=blankPlan();next.editingId=null;});closeSheet();navigate('calc');pickItem();});}else{navigate('calc');if(!state.draft.lines.length)pickItem();else toast('Настрой расчёт и сохрани новый маркет');}break;
  case 'event-detail':eventDetail(id);break;
  case 'event-sale':saleForm(id);break;
  case 'finish-event':saleForm(id,false,true);break;
  case 'event-meta':eventMeta(id);break;
  case 'edit-event':await commit(next=>{const event=next.events.find(e=>e.id===id);if(event.sales.length||event.status==='completed')throw new Error('После продаж план менять нельзя.');next.draft=clone(event.plan);next.editingId=id;});closeSheet();navigate('calc');break;
  case 'copy-event':openForm('Повторить маркет?','<p class="sheet-description">План заменит текущий черновик. Количество ограничится свободным мерчем.</p>','Создать черновик',async()=>{await commit(next=>{next.draft=clone(next.events.find(e=>e.id===id).plan);next.editingId=null;next.draft.lines=next.draft.lines.map(l=>{const item=next.inventory.find(i=>i.id===l.itemId);return {...l,name:item.name,category:item.category,photo:item.photo,color:item.color,cost:item.cost,qty:Math.min(l.qty,available(next,l.itemId))};}).filter(l=>l.qty>0&&!next.inventory.find(i=>i.id===l.itemId)?.archived);next.draft.promos=next.draft.promos.filter(p=>p.parts.every(x=>next.draft.lines.some(l=>l.itemId===x.itemId)));});closeSheet();navigate('calc');});break;
  case 'toggle-check':await commit(next=>{const c=next.events.find(x=>x.id===id).checklist.find(x=>x.id===button.dataset.check);c.done=!c.done;});eventDetail(id);break;
  case 'add-check':openForm('Добавить пункт',field('Что подготовить?','text','','text','required maxlength="300"'),'Добавить',async f=>{await commit(next=>next.events.find(x=>x.id===id).checklist.push({id:uid(),text:f.elements.text.value.trim(),done:false}));eventDetail(id);});break;
  case 'undo-event-sale':openForm('Отменить последнюю продажу?','<p class="sheet-description">Последняя запись удалится. Мерч вернётся в остаток маркета.</p>','Отменить запись',async()=>{await commit(next=>{const event=next.events.find(x=>x.id===id);if(event.status==='completed')throw new Error('Сначала открой маркет снова.');const last=event.sales.pop();for(const [itemId,q]of Object.entries(last.counts)){const item=next.inventory.find(i=>i.id===itemId);item.qty+=q;delete item.archived;}event.status=event.sales.length?'live':'planned';},'Продажа отменена');eventDetail(id);});break;
  case 'reopen-event':await commit(next=>{const event=next.events.find(x=>x.id===id);event.status=event.sales.length?'live':'planned';delete event.completedAt;},'Маркет снова открыт');eventDetail(id);break;
  case 'new-shelf':shelfForm();break;
  case 'edit-shelf':shelfForm(id);break;
  case 'shelf-detail':shelfDetail(id);break;
  case 'shelf-sale':saleForm(id,true);break;
  case 'shelf-transfer':shelfTransferForm(id,button.dataset.return==='1');break;
  case 'shelf-item':shelfItemForm(id,button.dataset.item);break;
  case 'checked-shelf':await commit(next=>{const s=next.shelves.find(x=>x.id===id);s.nextCheck=dayPlus(today(),s.interval);},'Дата проверки обновлена');shelfDetail(id);break;
  case 'pay-rent':rentForm(id);break;
  case 'undo-rent':openForm('Отменить платёж?','<p class="sheet-description">Платёж удалится из отчёта.</p>','Отменить платёж',async()=>{await commit(next=>{const s=next.shelves.find(x=>x.id===id),index=s.payments.findIndex(p=>p.id===button.dataset.payment),p=s.payments[index];if(index===s.payments.length-1)s.nextRent=p.previousNextRent||today();s.payments.splice(index,1);});shelfDetail(id);});break;
  case 'undo-shelf-sale':openForm('Отменить последнюю продажу?','<p class="sheet-description">Последняя запись удалится. Мерч вернётся на полку и в инвентарь.</p>','Отменить запись',async()=>{await commit(next=>{const s=next.shelves.find(x=>x.id===id),last=s.sales.pop();for(const [itemId,qty]of Object.entries(last.counts)){s.stock[itemId]=(s.stock[itemId]||0)+qty;{const item=next.inventory.find(i=>i.id===itemId);item.qty+=qty;delete item.archived;}}},'Продажа отменена');shelfDetail(id);});break;
  case 'ack-backup-notice':await commit(next=>{next.settings.backupNoticeSeen=true;});closeSheet();break;
  case 'open-backups':await commit(next=>{next.settings.backupNoticeSeen=true;});closeSheet();navigate('settings');break;
  case 'backup-notice-info':backupNotice();break;
  case 'export':await exportBackup();break;
  case 'import':importBackup();break;
}}catch(err){toast(err.message);}});
function liveNumber(el){if(!el.dataset.change||el.value===''||!el.checkValidity())return false;const value=Number(el.value);if(!Number.isFinite(value))return false;switch(el.dataset.change){case'profit':state.draft.profit=value;break;case'table':state.draft.table=value;break;case'round':state.draft.round=value;break;case'expense':state.draft.expenses.find(x=>x.id===el.dataset.id).amount=value;break;case'line-qty':state.draft.lines.find(x=>x.itemId===el.dataset.id).qty=value;break;case'line-price':state.draft.lines.find(x=>x.itemId===el.dataset.id).price=value;break;case'line-cost':state.draft.lines.find(x=>x.itemId===el.dataset.id).cost=value;break;case'promo-count':state.draft.promos.find(x=>x.id===el.dataset.id).count=value;break;default:return false;}return true;}
document.addEventListener('input',e=>{if(busy||storageReadOnly)return;const el=e.target;if(liveNumber(el)){persistDraft();scheduleNumbers();}if(el.id==='inventory-search'){search=el.value;const list=state.inventory.filter(i=>!i.archived&&(!categoryFilter||i.category===categoryFilter)&&i.name.toLowerCase().includes(search.toLowerCase()));document.querySelector('#inventory-grid').innerHTML=list.map(inventoryCard).join('')||'<p class="small muted">Ничего не найдено.</p>';hydratePhotos();}if(el.dataset.live==='percent'){state.draft.sellPercent=Number(el.value);el.style.setProperty('--range-pct',el.value+'%');persistDraft();scheduleNumbers();}if(el.dataset.live==='promo'){state.draft.promos.find(p=>p.id===el.dataset.id).count=Number(el.value);el.style.setProperty('--range-pct',(Number(el.max)?Number(el.value)/Number(el.max)*100:0)+'%');el.closest('.promo-card').querySelector('[data-change=promo-count]').value=el.value;persistDraft();scheduleNumbers();}if(el.dataset.live==='price'){const line=state.draft.lines.find(l=>l.itemId===el.dataset.id);line.price=Number(el.value);el.style.setProperty('--range-pct',Number(el.value)/Number(el.max)*100+'%');const numberInput=el.parentElement.querySelector('[data-change=line-price]');if(numberInput)numberInput.value=el.value;persistDraft();scheduleNumbers();}});
document.addEventListener('change',e=>{if(busy)return;const el=e.target;if(el.id==='category-filter'){categoryFilter=el.value;render();return;}if(el.id==='report-month'){reportMonth=el.value||today().slice(0,7);shelfDetail(el.dataset.id);return;}if(['percent','promo'].includes(el.dataset.live)){const p=projection(state.draft);for(const b of state.draft.promos)b.count=p.bundles.find(x=>x.id===b.id).count;persistDraft();updateNumbers();return;}const kind=el.dataset.change;if(!kind)return;const value=Number(el.value);if(!el.checkValidity()||!Number.isFinite(value)){el.reportValidity();render();return;}switch(kind){case'profit':state.draft.profit=value;break;case'table':state.draft.table=value;break;case'round':state.draft.round=value;break;case'expense':state.draft.expenses.find(x=>x.id===el.dataset.id).amount=value;break;case'line-qty':state.draft.lines.find(l=>l.itemId===el.dataset.id).qty=value;break;case'line-price':state.draft.lines.find(l=>l.itemId===el.dataset.id).price=value;break;case'line-cost':state.draft.lines.find(l=>l.itemId===el.dataset.id).cost=value;break;case'promo-count':state.draft.promos.find(p=>p.id===el.dataset.id).count=value;break;}const p=projection(state.draft);for(const b of state.draft.promos)b.count=p.bundles.find(x=>x.id===b.id).count;persistDraft();updateNumbers();});
sheet.addEventListener('click',e=>{if(e.target===sheet){const rect=sheet.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeSheet();}});

function flushState(){clearTimeout(saveTimer);if(state&&!isDemo&&!storageReadOnly){try{localStorage.setItem('solyanka-state-v1',JSON.stringify(state));}catch{}saveState(state).catch(()=>{});}}
window.addEventListener('pagehide',flushState);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='hidden')flushState();});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state)applyTheme();});
function initTelegram(){const tg=globalThis.Telegram?.WebApp;if(!tg?.initData)return;try{tg.ready();tg.expand();tg.onEvent('themeChanged',()=>{if(state)applyTheme();});const updateSafe=()=>{const inset=tg.contentSafeAreaInset||{};document.documentElement.style.setProperty('--safe-top',`${inset.top||0}px`);document.documentElement.style.setProperty('--safe-bottom',`max(env(safe-area-inset-bottom,0px), ${inset.bottom||0}px)`);};tg.onEvent('contentSafeAreaChanged',updateSafe);updateSafe();if(state)applyTheme();}catch{}}
try{const loaded=isDemo?demoState():await loadState();state=loaded||emptyState();validateState(state);render();initTelegram();if(!globalThis.Telegram?.WebApp)window.addEventListener('load',initTelegram,{once:true});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});if(!isDemo&&state.settings.backupNoticeSeen!==true)backupNotice();}catch(err){storageReadOnly=true;state=emptyState();render();info('Ошибка загрузки','Данные не изменены. Перезагрузи приложение или восстанови копию в настройках.','Причина: '+esc(err.message));}

// Progressive forms retain the original controls and values while hiding later
// fields. Native validation runs only for the current step, then for all fields.
function progressiveForm(form,titles,groups){
 const nodes=[...form.children].filter(n=>!n.matches('.form-error,.sheet-footer'));
 const pages=groups.map(indices=>{const section=document.createElement('section');section.className='form-page';for(const i of indices)if(nodes[i])section.append(nodes[i]);form.insertBefore(section,form.querySelector('.form-error'));return section;});
 const heading=document.createElement('p');heading.className='form-step-label';form.prepend(heading);
 const footer=form.querySelector('.sheet-footer'),submit=footer.querySelector('[type=submit]'),label=submit.textContent;
 const back=document.createElement('button');back.type='button';back.className='button secondary';back.textContent='Назад';footer.prepend(back);
 const originallyDisabled=new Set([...form.elements].filter(e=>e.disabled));let step=0;
 const draw=()=>{pages.forEach((page,i)=>{page.hidden=i!==step;for(const field of page.querySelectorAll('input,select,textarea'))field.disabled=i!==step||originallyDisabled.has(field);});heading.textContent=`${step+1} из ${pages.length} · ${titles[step]}`;back.hidden=step===0;submit.textContent=step===pages.length-1?label:'Далее';form.querySelector('.form-error').textContent='';sheet.scrollTop=0;};
 back.onclick=()=>{step--;draw();};
 form.addEventListener('submit',e=>{if(step<pages.length-1){e.preventDefault();e.stopImmediatePropagation();step++;draw();}else{for(const page of pages)for(const field of page.querySelectorAll('input,select,textarea'))field.disabled=originallyDisabled.has(field);}},true);
 draw();
}

// Zero is a placeholder until the user edits; blur restores it if left empty.
document.addEventListener('focusin',e=>{const el=e.target;if(el.matches('input[type=number]')&&Number(el.value)===0&&el.value!==''){el.dataset.emptyZero='1';el.value='';el.placeholder||='0';}});
document.addEventListener('focusout',e=>{const el=e.target;if(el.matches('input[type=number]')&&el.dataset.emptyZero){if(el.value==='')el.value='0';delete el.dataset.emptyZero;}},true);
let touchOrigin=null;
document.addEventListener('touchstart',e=>{const focused=document.activeElement;touchOrigin=focused?.matches('input:not([type=range]):not([type=checkbox]),textarea')&&!e.target.closest('input,textarea,select')?{y:e.touches[0]?.clientY,focused}:null;},{passive:true});
document.addEventListener('touchmove',e=>{if(touchOrigin&&Math.abs(e.touches[0].clientY-touchOrigin.y)>14){touchOrigin.focused.blur();touchOrigin=null;}},{passive:true});
document.addEventListener('touchend',()=>{touchOrigin=null;},{passive:true});

function detailPages(key,titles,markers){
 const body=sheet.querySelector('.sheet-body'),nodes=[...body.children];
 const nav=document.createElement('div');nav.className='segmented detail-tabs';nav.setAttribute('aria-label','Разделы площадки');
 const pages=titles.map(()=>{const section=document.createElement('section');section.className='detail-page';return section;});
 let page=0;
 for(const node of nodes){if(node.matches('.detail-title,.report-toolbar')){const match=markers.find(([text])=>node.textContent.startsWith(text));if(match)page=match[1];}pages[page].append(node);}
 const select=index=>{detailPage[key]=index;pages.forEach((el,i)=>{el.hidden=i!==index;});[...nav.children].forEach((button,i)=>{button.classList.toggle('active',i===index);button.setAttribute('aria-pressed',String(i===index));});sheet.scrollTop=0;};
 titles.forEach((title,i)=>{const button=document.createElement('button');button.type='button';button.textContent=title;button.onclick=()=>select(i);nav.append(button);});
 body.append(nav,...pages);select(detailPage[key]||0);
}

function prepareInputs(root){for(const el of root.querySelectorAll('input[type=number]')){el.inputMode=el.step==='1'?'numeric':'decimal';el.enterKeyHint='done';}}
